<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';
use Kulturhus\Verein\{Database,Registry,WebsiteCalendar};
$checks=0;
function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException($label);++$checks;echo "PASS $label\n";}
function denied(callable $fn,string $label):void{try{$fn();}catch(DomainException){check(true,$label);return;}throw new RuntimeException($label);}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);
$db->exec("INSERT INTO clubs VALUES('a','A'),('b','B');INSERT INTO actors(id,club_id,role) VALUES('manager','a','members'),('other','b','members'),('editor','a','editor')");
$registry=new Registry($db,'manager');$person=$registry->saveContact(null,0,'person','Testmitglied','','');
$db->prepare("INSERT INTO actors(id,club_id,role,contact_id) VALUES('member','a','member',?)")->execute([$person]);
$internal=$registry->saveAppointment(null,0,['title'=>'Interne Sitzung','start'=>'2026-09-10T18:00','end'=>'2026-09-10T19:00','category'=>'vorstand'],[]);
$row=['id'=>10,'external_id'=>'eb-10','title'=>'Kulturabend','summary'=>'<p>Öffentlich &amp; Kultur</p>','start_at'=>strtotime('2026-09-10T20:00:00+02:00'),'end_at'=>strtotime('2026-09-10T22:00:00+02:00'),'venue_name'=>'Kulturhus','venue_address'=>'Jaderberg','path'=>'/veranstaltungen/kulturabend/','status'=>'live'];
$calls=0;$feed=['complete'=>true,'rows'=>[$row,$row,array_replace($row,['id'=>11])]];
$provider=new WebsiteCalendar('a',function()use(&$calls,&$feed){++$calls;return $feed;});
$r=new Registry($db,'manager',$provider);$member=new Registry($db,'member',$provider);
check(count($r->appointments('2026-09-01','2026-10-01'))===2,'internal and website events combined without duplicate source events');
check($r->appointments('2026-09-01','2026-10-01')[1]['id']==='website:10','events sorted by actual start');
check(count($member->appointments('2026-09-01','2026-10-01'))===1,'member sees public event but no private uninvited meeting');
check($member->appointment('website:10')['description']==='Öffentlich & Kultur','public detail uses plain event data');
check($calls===1,'one source snapshot per request');
check((int)$db->query('SELECT COUNT(*) FROM appointments')->fetchColumn()===1,'source events do not create duplicate database rows');
denied(fn()=>$member->appointment($internal),'internal invitation access remains enforced');
denied(fn()=>(new Registry($db,'other',$provider))->appointment('website:10'),'website source bound to configured club');
denied(fn()=>(new Registry($db,'editor',$provider))->appointment('website:10'),'no implicit calendar rights for editors');
denied(fn()=>$r->saveAppointment('website:10',0,[],[]),'source date cannot diverge through manual save');
denied(fn()=>$r->deleteAppointment('website:10',0),'source event cannot be deleted as an internal appointment');
denied(fn()=>$member->respond('website:10','ja'),'source event creates no internal invitation');
$feed['rows']=[array_replace($row,['title'=>'Neuer Titel','start_at'=>strtotime('2026-10-01T00:15:00+02:00'),'end_at'=>0])];
$r=new Registry($db,'manager',new WebsiteCalendar('a',fn()=>$feed));
check(count($r->appointments('2026-09-01','2026-10-01'))===1,'rescheduling removes old calendar occurrence');
check(count($r->appointments('2026-10-01','2026-10-02'))===1,'Berlin midnight and event with unknown end handled');
check($r->appointment('website:10')['title']==='Neuer Titel'&&!$r->appointment('website:10')['end_known'],'next request gets title and unknown end without invented duration');
$feed['rows'][0]['status']='canceled';$r=new Registry($db,'manager',new WebsiteCalendar('a',fn()=>$feed));
check(str_starts_with($r->appointment('website:10')['title'],'Abgesagt:'),'cancellations clearly marked');
$feed['rows']=[];$r=new Registry($db,'manager',new WebsiteCalendar('a',fn()=>$feed));
denied(fn()=>$r->appointment('website:10'),'withdrawn source event disappears');
$r=new Registry($db,'manager',new WebsiteCalendar('a',static function(){throw new DomainException('offline');}));
check(count($r->appointments('2026-09-01','2026-10-01'))===1&&$r->calendarNotice()!=='','outage preserves internal calendar with visible incompleteness notice');
$bad=new WebsiteCalendar('a',fn()=>['complete'=>false,'rows'=>[$row]]);
check($bad->appointments('a','2026-01-01','2027-01-01')===[]&&$bad->notice()!=='','partial source response not accepted as full snapshot');
echo "$checks website calendar checks passed\n";
